import{_ as o,a0 as l,w as u,s,ao as p,I as a,x as i,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"遷移到 Linux ：入門介紹 | LCTT x X-CMD","titleTemplate":false,"description":"遷移到 Linux ：入門介紹 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"遷移到 Linux ：入門介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"遷移到 Linux ：入門介紹 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171031 Migrating to Linux- An Introduction","title":"遷移到 Linux ：入門介紹","tag":"201801","desc":""},"relativePath":"201801/20171031 Migrating to Linux- An Introduction.md","filePath":"[post].md"}'),x={name:"201801/20171031 Migrating to Linux- An Introduction.md"};function d(L,n,m,b,f,h){const t=l("Link");return u(),s("div",null,[n[16]||(n[16]=p('<h1 id="遷移到-linux-入門介紹" tabindex="-1">遷移到 Linux ：入門介紹 <a class="header-anchor" href="#遷移到-linux-入門介紹" aria-label="Permalink to “遷移到 Linux ：入門介紹”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/migrating-to-linux.jpg?itok=sjcGK0SY" alt=""></p><blockquote><p>這個新文章系列將幫你從其他操作系統遷移到 Linux。</p></blockquote><p>運行 Linux 的計算機系統到遍佈在每個角落。Linux 運行着從谷歌搜索到“臉書”等等各種互聯網服務。Linux 也在很多設備上運行，包括我們的智能手機、電視，甚至汽車。當然，Linux 也可以運行在您的桌面系統上。如果您是 Linux 新手，或者您想在您的桌面計算機上嘗試一些不同的東西，這篇文章將簡要地介紹其基礎知識，並幫助您從另一個系統遷移到 Linux。</p><p>切換到不同的操作系統可能是一個挑戰，因為每個操作系統都提供了不同的操作方法。其在一個系統上的<ruby>習慣<rt>second nature</rt></ruby>可能會對另一個系統的使用形成阻撓，因此我們需要到網上或書本上查找怎樣操作。</p><h3 id="windows-與-linux-的區別" tabindex="-1">Windows 與 Linux 的區別 <a class="header-anchor" href="#windows-與-linux-的區別" aria-label="Permalink to “Windows 與 Linux 的區別”">​</a></h3><p>（LCTT 譯註：本節標題 Vive la différence ，來自於法語，意即“差異萬歲”——來自於 wiktionary）</p><p>要開始使用 Linux，您可能會注意到，Linux 的打包方式不同。在其他操作系統中，許多組件被捆綁在一起，只是該軟件包的一部分。然而，在 Linux 中，每個組件都被分別調用。舉個例子來説，在 Windows 下，圖形界面只是操作系統的一部分。而在 Linux 下，您可以從多個圖形環境中進行選擇，比如 GNOME、KDE Plasma、Cinnamon 和 MATE 等。</p><p>從更高層面上看，一個 Linux 包括以下內容：</p><ol><li>內核</li><li>駐留在磁盤上的系統程序和文件</li><li>圖形環境</li><li>包管理器</li><li>應用程序</li></ol><h3 id="內核" tabindex="-1">內核 <a class="header-anchor" href="#內核" aria-label="Permalink to “內核”">​</a></h3><p>操作系統的核心稱為<ruby>內核<rt>kernel</rt></ruby>。內核是引擎罩下的引擎。它允許多個應用程序同時運行，並協調它們對公共服務和設備的訪問，從而使所有設備運行順暢。</p><h3 id="系統程序和文件" tabindex="-1">系統程序和文件 <a class="header-anchor" href="#系統程序和文件" aria-label="Permalink to “系統程序和文件”">​</a></h3><p>系統程序以標準的文件和目錄的層次結構位於磁盤上。這些系統程序和文件包括後台運行的服務（稱為<ruby>守護進程<rt>deamon</rt></ruby>）、用於各種操作的實用程序、配置文件和日誌文件。</p><p>這些系統程序不是在內核中運行，而是執行基本系統操作的程序——例如，設置日期和時間，以及連接網絡以便你可以上網。</p><p>這裏包含了<ruby>初始化<rt>init</rt></ruby>程序——它是最初運行的程序。該程序負責啓動所有後台服務（如 Web 服務器）、啓動網絡連接和啓動圖形環境。這個初始化程序將根據需要啓動其它系統程序。</p><p>其他系統程序為簡單的任務提供便利，比如添加用户和組、更改密碼和配置磁盤。</p><h3 id="圖形環境" tabindex="-1">圖形環境 <a class="header-anchor" href="#圖形環境" aria-label="Permalink to “圖形環境”">​</a></h3><p>圖形環境實際上只是更多的系統程序和文件。圖形環境提供了常用的帶有菜單的窗口、鼠標指針、對話框、狀態和指示器等。</p><p>需要注意的是，您不是必須需要使用原本安裝的圖形環境。如果你願意，你可以把它換成其它的。每個圖形環境都有不同的特性。有些看起來更像 Apple OS X，有些看起來更像 Windows，有些則是獨特的而不試圖模仿其他的圖形界面。</p><h3 id="包管理器" tabindex="-1">包管理器 <a class="header-anchor" href="#包管理器" aria-label="Permalink to “包管理器”">​</a></h3><p>對於來自不同操作系統的人來説，<ruby>包管理器<rt>package manager</rt></ruby>比較難以掌握，但是現在有一個人們非常熟悉的類似的系統——應用程序商店。軟件包系統實際上就是 Linux 的應用程序商店。您可以使用包管理器來選擇您想要的應用程序，而不是從一個網站安裝這個應用程序，而從另一個網站來安裝那個應用程序。然後，包管理器會從預先構建的開源應用程序的中心倉庫安裝應用程序。</p><h3 id="應用程序" tabindex="-1">應用程序 <a class="header-anchor" href="#應用程序" aria-label="Permalink to “應用程序”">​</a></h3><p>Linux 附帶了許多預安裝的應用程序。您可以從包管理器獲得更多。許多應用程序相當棒，另外一些還需要改進。有時，同一個應用程序在 Windows 或 Mac OS 或 Linux 上運行的版本會不同。</p><p>例如，您可以使用 Firefox 瀏覽器和 Thunderbird (用於電子郵件)。您可以使用 LibreOffice 作為 Microsoft Office 的替代品，並通過 Valve 的 Steam 程序運行遊戲。您甚至可以在 Linux 上使用 WINE 來運行一些 Windows 原生的應用程序。</p><h3 id="安裝-linux" tabindex="-1">安裝 Linux <a class="header-anchor" href="#安裝-linux" aria-label="Permalink to “安裝 Linux”">​</a></h3><p>第一步通常是安裝 Linux 發行版。你可能聽説過 Red Hat、Ubuntu、Fedora、Arch Linux 和 SUSE，等等。這些都是 Linux 的不同發行版。</p><p>如果沒有 Linux 發行版，則必須分別安裝每個組件。許多組件是由不同人羣開發和提供的，因此單獨安裝每個組件將是一項冗長而乏味的任務。幸運的是，構建發行版的人會為您做這項工作。他們抓取所有的組件，構建它們，確保它們可以在一起工作，然後將它們打包在一個單一的安裝套件中。</p><p>各種發行版可能會做出不同的選擇、使用不同的組件，但它仍然是 Linux。在一個發行版中開發的應用程序通常在其他發行版上運行的也很好。</p>',29)),a("p",null,[n[1]||(n[1]=i("如果你是一個 Linux 初學者，想嘗試 Linux，我推薦",-1)),e(t,{href:"https://www.ubuntu.com/download/desktop"},{default:r(()=>[...n[0]||(n[0]=[i("安裝 Ubuntu",-1)])]),_:1}),n[2]||(n[2]=i("。還有其他的發行版也可以嘗試: Linux Mint、Fedora、Debian、Zorin OS、Elementary OS 等等。在以後的文章中，我們將介紹 Linux 系統的其他方面，並提供關於如何開始使用 Linux 的更多信息。",-1))]),n[17]||(n[17]=a("hr",null,null,-1)),a("p",null,[n[4]||(n[4]=i("via: ",-1)),e(t,{href:"https://www.linux.com/blog/learn/intro-to-linux/2017/10/migrating-linux-introduction"},{default:r(()=>[...n[3]||(n[3]=[i("https://www.linux.com/blog/learn/intro-to-linux/2017/10/migrating-linux-introduction",-1)])]),_:1})]),a("p",null,[n[8]||(n[8]=i("作者：",-1)),e(t,{href:"https://www.linux.com/users/johnbonesio"},{default:r(()=>[...n[5]||(n[5]=[i("John Bonesio",-1)])]),_:1}),n[9]||(n[9]=i(" 譯者：",-1)),e(t,{href:"https://github.com/stevenzdg988"},{default:r(()=>[...n[6]||(n[6]=[i("stevenzdg988",-1)])]),_:1}),n[10]||(n[10]=i(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:r(()=>[...n[7]||(n[7]=[i("wxy",-1)])]),_:1})]),a("p",null,[n[13]||(n[13]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[11]||(n[11]=[i("LCTT",-1)])]),_:1}),n[14]||(n[14]=i(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:r(()=>[...n[12]||(n[12]=[i("Linux中國",-1)])]),_:1}),n[15]||(n[15]=i(" 榮譽推出",-1))])])}const k=o(x,[["render",d]]);export{T as __pageData,k as default};
